 auto restored=prepareRestore(c,paused,{},safe);
 need(restored.scene->world().player().animation.paused()&&restored.scene->captureWarehouseState()==paused.warehouse,"Paused animation is preserved exactly through v2 candidate restore");
 auto legacy=snapshot;legacy.warehouse["version"]=1;
 for(auto& actor:legacy.warehouse["actors"]){actor["animation"].erase(8);}
 legacy.warehouse["actors"][0]["animation"][6]=1;
 std::cout<<"02 restoring original v1\n";
 auto older=prepareRestore(c,decodeSave(c,encodeSave(c,legacy)),{},safe);
 const auto upgraded=older.scene->captureWarehouseState();
 need(!older.scene->world().player().animation.paused()&&upgraded.at("version")==2&&upgraded.at("actors")[0].at("animation")[6]==1,"v1 loads its original continuous type, with no invented pause or silent old-field reinterpretation");
